  [{"id":"REQ-22","quote":"remainder must be allocated without loss","evidence":[{"file":"packages/contracts/src/Raffle.sol","lines":"L540","quote":"uint256 protocolFee = Math.mulDiv(grossPot, RaffleConstants.PROTOCOL_FEE_BPS, RaffleConstants.BPS);","role":"Floor on the aggregate protocol fee; any truncation is absorbed by the sponsor residual"},{"file":"packages/contracts/src/Raffle.sol","lines":"L544","quote":"sponsorAmount = grossPot - protocolFee;","role":"NftWon: sponsor is the residual, so fee + sponsor == grossPot"},{"file":"packages/contracts/src/Raffle.sol","lines":"L546-L547","quote":"sponsorAmount = grossPot - protocolFee - cashAmount;","role":"CashWon: winner is floored at L546 and sponsor is the residual, so fee + cash + sponsor == grossPot"},{"file":"packages/contracts/src/Raffle.sol","lines":"L553-L555","quote":"unsettledPot = 0;","role":"Whole pot leaves unsettledPot in the same frame that sponsorProceeds and protocolFees are assigned; nothing left unallocated"},{"file":"packages/contracts/src/Raffle.sol","lines":"L534","quote":"if (settlementComplete) revert SettlementAlreadyComplete();","role":"Settlement is one-shot, so the assignments at L554-L555 are equivalent to additions to zero"},{"file":"packages/contracts/src/Raffle.sol","lines":"L223","quote":"uint256 grossAmount = uint256(entryCount) * ENTRY_PRICE;","role":"Pot grows only in ENTRY_PRICE multiples (with L233), so grossPot = n*1e6 and the floor never truncates on reachable inputs"},{"file":"packages/contracts/src/Raffle.sol","lines":"L296-L298","quote":"remainingRefundLiability = liability;","role":"Refund outcome: the entire pot becomes the refund liability"},{"file":"packages/contracts/src/Raffle.sol","lines":"L363-L368","quote":"amount = aggregateEntries * ENTRY_PRICE;","role":"Refund per ticket is entryCount*ENTRY_PRICE with no division; the liability decrement is checked (L368)"},{"file":"packages/contracts/node_modules/@openzeppelin/contracts/token/ERC721/ERC721.sol","lines":"L426-L4